-- HoodItemMeshes setup: paste ALL of this into Studio's Command Bar (View > Command Bar) and press Enter, right after
-- importing hood/art/models/items/HoodItemMeshes.fbx with the 3D Importer (see hood/art/MESH_IMPORT.md).
-- (Generated by hood/tools/blender/export_item_meshes.py from studio_item_meshes.template.lua: edit the template.)
--
-- What it does, in one go (safe to run again after a re-import):
--   * finds the imported MeshParts (named <ItemId>__<Group>__<Material>_<hex> by the exporter) in the selection, or
--     anywhere in Workspace when nothing is selected;
--   * files them into ReplicatedStorage.HoodItemMeshes as one Model per item id (a box's lid parts in its `Lid` model),
--     replacing an item that is already there;
--   * sets each MeshPart's Color and Material from its name (no textures), anchors it, turns collisions off;
--   * stores each item's design bounds (DesignMin / DesignMax) so the game places it exactly, whatever unit the
--     importer used;
--   * removes the empty imported model and prints what it made. Then: File > Save (or Publish).
local DESIGN = { -- item id = { min x, y, z, max x, y, z } in design studs (the exporter's manifest)
--@DESIGN@
}
local ReplicatedStorage = game:GetService('ReplicatedStorage')
local Selection = game:GetService('Selection')
local ChangeHistory = game:GetService('ChangeHistoryService')

local roots = Selection:Get()
if #roots == 0 then roots = { workspace } end
local found = {}
for _, root in roots do
	local list = root:GetDescendants()
	if root:IsA('MeshPart') then table.insert(list, root) end
	for _, d in list do
		if d:IsA('MeshPart') and d.Name:find('__', 1, true) then table.insert(found, d) end
	end
end
if #found == 0 then
	warn('[HoodItemMeshes] no imported item MeshParts found. Import HoodItemMeshes.fbx first (MESH_IMPORT.md step 2), then run this again.')
	return
end

local _, recording = pcall(function() return ChangeHistory:TryBeginRecording('HoodItemMeshes setup') end)
local folder = ReplicatedStorage:FindFirstChild('HoodItemMeshes')
if not folder then
	folder = Instance.new('Folder')
	folder.Name = 'HoodItemMeshes'
	folder.Parent = ReplicatedStorage
end
local items, fresh, containers, unknown = {}, {}, {}, {}
local function item(id)
	if items[id] then return items[id] end
	local old = folder:FindFirstChild(id)
	if old and not fresh[id] then old:Destroy() end
	local m = Instance.new('Model')
	m.Name = id
	m.Parent = folder
	items[id], fresh[id] = m, true
	return m
end
for _, mp in found do
	local id, group, mat, hex = mp.Name:match('^(.-)__(.-)__(%a+)_(%x%x%x%x%x%x)$')
	if not id then
		table.insert(unknown, mp.Name)
		continue
	end
	local top = mp.Parent
	while top and top.Parent and top.Parent ~= workspace and top.Parent ~= game do top = top.Parent end
	if top and top ~= mp and top.Parent == workspace then containers[top] = true end
	local m = item(id)
	local into = m
	if group == 'Lid' then
		into = m:FindFirstChild('Lid')
		if not into then
			into = Instance.new('Model')
			into.Name = 'Lid'
			into.Parent = m
		end
	end
	for _, c in mp:GetChildren() do
		if c:IsA('SurfaceAppearance') or c:IsA('Decal') or c:IsA('Texture') then c:Destroy() end
	end
	pcall(function() mp.TextureID = '' end)
	mp.Color = Color3.fromHex(hex)
	local ok, material = pcall(function() return Enum.Material[mat] end)
	mp.Material = ok and material or Enum.Material.SmoothPlastic
	mp.Reflectance = mat == 'Foil' and 0.2 or mat == 'Metal' and 0.15 or 0.06
	mp.Transparency = mat == 'Glass' and 0.35 or 0
	mp.CastShadow = not (mat == 'Neon' or mat == 'Glass')
	mp.Anchored, mp.CanCollide, mp.CanTouch, mp.CanQuery = true, false, false, false
	pcall(function() mp.CollisionFidelity = Enum.CollisionFidelity.Box end)
	pcall(function() mp.DoubleSided = false end)
	mp.Name = group .. '_' .. mat .. '_' .. hex
	mp.Parent = into
end

-- design bounds, and a check that the import kept the exporter's axes and proportions
local warned = 0
local scales = {}
for id, m in items do
	local cf, size = m:GetBoundingBox()
	local d = DESIGN[id]
	if d then
		local dmin, dmax = Vector3.new(d[1], d[2], d[3]), Vector3.new(d[4], d[5], d[6])
		m:SetAttribute('DesignMin', dmin)
		m:SetAttribute('DesignMax', dmax)
		local ds = dmax - dmin
		local k = size.Y / math.max(ds.Y, 1e-3)
		table.insert(scales, k)
		local ex, ez = size.X / math.max(ds.X * k, 1e-3), size.Z / math.max(ds.Z * k, 1e-3)
		if math.abs(ex - 1) > 0.08 or math.abs(ez - 1) > 0.08 then
			warned += 1
			if warned <= 5 then
				warn(('[HoodItemMeshes] %s came in turned or stretched (size %s, expected %s x %.3f). Re-import with World Forward = Front and World Up = Top.'):format(id, tostring(size), tostring(ds), k))
			end
		end
	end
	m:SetAttribute('ItemMesh', true)
	m.WorldPivot = cf - Vector3.new(0, size.Y / 2, 0)
end
for c in containers do
	local left = 0
	for _, d in c:GetDescendants() do
		if d:IsA('BasePart') then left += 1 end
	end
	if left == 0 then c:Destroy() end
end
table.sort(scales)
local n, parts = 0, 0
local names = {}
for id, m in items do
	n += 1
	table.insert(names, id)
	for _, d in m:GetDescendants() do
		if d:IsA('MeshPart') then parts += 1 end
	end
end
table.sort(names)
if recording then pcall(function() ChangeHistory:FinishRecording(recording, Enum.FinishRecordingOperation.Commit) end) end
print(('[HoodItemMeshes] done: %d items, %d MeshParts in ReplicatedStorage.HoodItemMeshes%s'):format(n, parts,
	#scales > 0 and (' (import scale x%.3f; the game rescales, so any is fine)'):format(scales[math.ceil(#scales / 2)]) or ''))
print('[HoodItemMeshes] ' .. table.concat(names, ', '))
if #unknown > 0 then warn('[HoodItemMeshes] skipped ' .. #unknown .. ' part(s) without an item name, e.g. ' .. unknown[1]) end
if warned == 0 then print('[HoodItemMeshes] all items have the right shape. Now File > Save (or Publish) the place.') end
